SELECT * FROM (
    SELECT ROWNUM AS rnum, a.* FROM (
        SELECT *
        FROM INQUIRIES_TB
        WHERE SALES_POST_ID = #{salesPostId}
        ORDER BY CREATED_DATE DESC
    ) a
    WHERE ROWNUM <= #{offset} + #{limit}
)
WHERE rnum > #{offset}

SELECT COUNT(*)
FROM INQUIRIES_TB
WHERE SALES_POST_ID = #{salesPostId}

SELECT ID, INQUIRIES_ID, ADMIN_ID, MESSAGE, CREATED_DATE
FROM RESPONSE_TB
WHERE INQUIRIES_ID = #{inquiriesId}

SELECT ID, USER_ID, SUBSTR(NICKNAME, 1, 4) || '****' AS NICKNAME, NAME, GENDER, PHONE, EMAIL, BIRTHDATE, ADDRESS, ADDRESS_DETAIL, ZIPCODE
FROM CUSTOMER_TB
WHERE ID = #{customerId}
